insert into public.cw_terms (unit, chapter, n, term, def, extra, story_ok) values
(1,1,1,'Health','A combination of physical, mental/emotional, and social well-being — not just the absence of disease.',false,true),
(1,1,2,'Wellness','The quality of life that results from taking positive steps toward achieving your full health potential.',false,true),
(1,1,3,'Health Triangle','A model showing the three sides of health: physical, mental/emotional, and social — all must be balanced.',false,true),
(1,1,4,'Lifestyle factors','Personal behaviors and habits that affect your long-term health, both positively and negatively.',false,true),
(1,1,5,'Health literacy','The ability to find, understand, evaluate, and apply health information to make responsible decisions.',false,true),
(1,1,6,'Heredity','The passing of traits from biological parents to their children through genes.',false,true),
(1,1,7,'Environment','All living and nonliving things around you, including your community, culture, and physical surroundings.',false,true),
(1,1,8,'Culture','The beliefs, values, and practices shared by a group of people — a major influence on health decisions.',false,true),
(1,1,9,'Peers','People of the same age who share similar interests; a powerful influence on teen health behavior.',false,true),
(1,1,10,'Risk behaviors','Actions or habits that increase the likelihood of negative outcomes to one''s health or others.',false,true),
(1,1,11,'Prevention','Taking action to avoid disease, injury, and other health problems before they occur.',false,true),
(1,1,12,'Abstinence','The deliberate decision to refrain from a risky behavior.',false,true),
(1,1,13,'Health promotion','The process of enabling people to increase control over and improve their health.',false,true),
(1,1,14,'Protective factors','Conditions or attributes that reduce the impact of risk factors on health outcomes.',false,true),
(1,1,15,'Attitude','A feeling or disposition toward a person, object, or idea that influences behavior.',false,true),
(1,1,16,'Spiritual health','A deep-seated sense of meaning and purpose in life.',false,true),
(1,1,17,'Chronic disease','An ongoing condition or illness such as heart disease, obesity, or cancer.',false,true),
(1,1,18,'Media','The various methods for communicating information.',false,true),
(1,1,19,'Technology','The tools and methods used to deliver media content.',false,true),
(1,1,20,'Cumulative risks','Related risks that increase in effect with each added risk.',false,true),
(1,1,21,'Health education','Providing accurate health information and teaching health skills to help people make healthy decisions.',false,true),
(1,1,22,'Healthy People 2030','A nationwide health promotion and disease prevention plan with goals set for the current decade.',false,true),
(1,1,23,'Health disparities','Differences in health outcomes among groups based on gender, race, education, disability, or location.',false,true),
(1,2,24,'Goal setting','The process of identifying something you want to accomplish and creating a plan to achieve it.',false,true),
(1,2,25,'SMART goals','Goals that are Specific, Measurable, Achievable, Realistic, and Time-bound.',false,true),
(1,2,26,'Decision making','A five-step process for making healthy, responsible choices.',false,true),
(1,2,27,'Values','The beliefs and principles that guide your behavior and decisions.',false,true),
(1,2,28,'Refusal skills','Strategies that help you say no to things that are harmful or illegal.',false,true),
(1,2,29,'Conflict resolution','A process for resolving disagreements in a peaceful, constructive way.',false,true),
(1,2,30,'Stress management','Techniques for controlling and reducing the physical and emotional effects of stress.',false,true),
(1,2,31,'Communication skills','The ability to share information clearly with others using listening, speaking, and body language.',false,true),
(1,2,32,'Self-management','The ability to control your emotions, behaviors, and actions to make healthy choices.',false,true),
(1,2,33,'Advocacy','Taking action to promote health and influence others to make positive choices.',false,true),
(1,2,34,'Accessing information','The skill of finding and evaluating reliable, accurate health information from valid sources.',false,true),
(1,2,35,'Analyzing influences','The ability to identify and examine the factors that affect health beliefs and behaviors.',false,true),
(1,2,36,'Health skills','Specific tools and strategies to maintain, protect, and improve all aspects of your health; also called life skills.',false,true),
(1,2,37,'Interpersonal communication','The exchange of thoughts, feelings, and beliefs between two or more people.',false,true),
(1,2,38,'Stress','The reaction of the body and mind to everyday challenges and demands.',false,true),
(1,2,39,'Decision-making skills','Steps that enable you to make a healthful decision.',false,true),
(1,2,40,'Goals','Things you aim for that take planning and work.',false,true),
(1,2,41,'Short-term goal','A goal you can reach in a short period of time.',false,true),
(1,2,42,'Long-term goal','A goal you plan to reach over an extended period of time.',false,true),
(1,2,43,'Action plan','A multistep strategy to identify and achieve your goals.',false,true),
(1,2,44,'Health consumer','Someone who purchases or uses health products or services.',false,true),
(1,2,45,'Advertising','A written or spoken media message designed to interest consumers in purchasing a product or service.',false,true),
(1,2,46,'Comparison shopping','Judging the benefits of different products by comparing factors such as quality, features, and cost.',false,true),
(1,2,47,'Warranty','A company''s or store''s written agreement to repair a product or refund your money if it does not function properly.',false,true),
(1,2,48,'Consumer advocates','People or groups whose purpose is to take on consumer issues and inform the public about potential problems.',false,true),
(1,2,49,'Malpractice','Failure by a health professional to meet accepted standards of care.',false,true),
(1,2,50,'Health fraud','The sale of worthless products or services that claim to prevent disease or cure health problems; also called quackery.',false,true),
(2,3,1,'Mental health','The state of your psychological and emotional well-being — how you think, feel, and cope with life.',false,true),
(2,3,2,'Emotions','Signals that tell your mind and body how to react to situations.',false,true),
(2,3,3,'Self-concept','The view you have of yourself — your strengths, weaknesses, thoughts, and feelings.',false,true),
(2,3,4,'Self-esteem','The confidence and satisfaction you have in yourself and your own abilities.',false,true),
(2,3,5,'Empathy','The ability to understand and share the feelings of another person.',false,true),
(2,3,6,'Emotional intelligence','The ability to recognize, understand, and manage your own emotions and recognize emotions in others.',false,true),
(2,3,7,'Resiliency','The ability to recover from setbacks, adapt to change, and keep going in the face of adversity.',false,true),
(2,3,8,'Grief','The emotional response to loss — a normal and necessary process that takes time.',false,true),
(2,3,9,'Coping strategies','Healthy ways of managing and reducing the emotional pain of difficult situations.',false,true),
(2,3,10,'Defense mechanisms','Unconscious mental strategies used to protect yourself from uncomfortable emotions.',false,true),
(2,3,11,'Positive affirmations','Statements that remind you of your strengths and help reinforce a positive self-image.',false,true),
(2,3,12,'Mindfulness','The practice of focusing attention on the present moment with openness and without judgment.',false,true),
(2,3,13,'Mental/emotional health','The ability to accept yourself and others, express and manage emotions, and deal with the demands and challenges of life.',false,true),
(2,3,14,'Competence','Having enough skills to do something successfully.',false,true),
(2,3,15,'Hierarchy of needs','A ranked list of needs essential to human growth and development, from basic physical needs up to reaching your full potential.',false,true),
(2,3,16,'Self-actualization','The drive to reach your full potential and become the best version of yourself.',false,true),
(2,3,17,'Personal identity','Your sense of yourself as a unique individual, shaped by your values, relationships, experiences, and beliefs.',false,true),
(2,3,18,'Role model','Someone whose success or behavior serves as an example for others.',false,true),
(2,3,19,'Personality','The complex set of characteristics that makes a person unique.',false,true),
(2,3,20,'Character','The distinctive qualities that describe how a person thinks, feels, and behaves.',false,true),
(2,3,21,'Integrity','A firm, consistent commitment to core ethical values.',false,true),
(2,3,22,'Constructive criticism','Honest, non-hostile feedback that points out problems and encourages improvement.',false,true),
(2,3,23,'Hormones','Chemicals produced by your glands that regulate the activities of different body cells.',false,true),
(2,3,24,'Hostility','The intentional use of unfriendly or offensive behavior toward others.',false,true),
(2,4,25,'Stress','The body''s and mind''s reaction to everyday demands and threats, real or perceived.',false,true),
(2,4,26,'Stressor','Any situation, event, or person that causes stress.',false,true),
(2,4,27,'Fight-or-flight response','The body''s automatic physiological reaction to a perceived threat — prepares to fight or flee.',false,true),
(2,4,28,'Adrenaline','The hormone released during stress that increases heart rate, blood pressure, and energy.',false,true),
(2,4,29,'Eustress','Positive stress that motivates and energizes, such as excitement before a sports event.',false,true),
(2,4,30,'Distress','Negative stress that feels overwhelming and harmful to health.',false,true),
(2,4,31,'Chronic stress','Ongoing, long-term stress that persists over weeks or months and damages health.',false,true),
(2,4,32,'Relaxation response','The body''s ability to slow down and recover after a stressful event.',false,true),
(2,4,33,'Time management','The practice of organizing and prioritizing tasks to reduce stress and increase productivity.',false,true),
(2,4,34,'Support network','Friends, family, and others who provide emotional encouragement and practical help.',false,true),
(2,4,35,'Burnout','A state of physical and emotional exhaustion from prolonged, unmanaged stress.',false,true),
(2,4,36,'Cortisol','The primary stress hormone; sustained high levels damage the immune system and cardiovascular health.',false,true),
(2,4,37,'General Adaptation Syndrome','The three-stage process (alarm, resistance, exhaustion) the body goes through when exposed to prolonged stress.',false,true),
(2,4,38,'Resilience','The ability to recover from stress, trauma, and adversity.',false,true),
(2,4,39,'Acute stress','Short-term, intense stress that passes once the event ends.',false,true),
(2,4,40,'Alarm stage','The first stage of the General Adaptation Syndrome, when the body detects a stressor and triggers fight-or-flight.',false,true),
(2,4,41,'Exhaustion stage','The final stage of the General Adaptation Syndrome, when long stress uses up the body''s reserves and illness becomes more likely.',false,true),
(2,4,42,'Reframing','Changing how you interpret a stressor.',false,true),
(2,4,43,'Post-traumatic growth','Developing greater strength, deeper relationships and clearer priorities after a very difficult experience.',false,true),
(2,4,44,'Progressive muscle relaxation','A stress technique of tensing and then relaxing muscle groups one at a time.',false,true),
(2,4,45,'Perception','The way you see, understand and interpret a situation.',true,true),
(2,4,46,'Psychosomatic Response','A physical reaction, like a headache or upset stomach, caused by stress or emotions instead of an injury or illness.',true,true),
(2,4,47,'Coping','Dealing successfully with difficult changes or problems in your life.',true,true),
(2,5,48,'Mental disorder','An illness that affects a person''s thinking, feeling, or behavior significantly enough to cause distress.',false,true),
(2,5,49,'Anxiety disorder','A category of mental health conditions characterized by excessive, persistent fear or worry.',false,true),
(2,5,50,'Depression','A mood disorder marked by persistent sadness, hopelessness, loss of interest, and low energy.',false,true),
(2,5,51,'Suicide','The act of intentionally ending one''s own life — a preventable public health crisis.',false,false),
(2,5,52,'Suicide prevention','Strategies and actions to recognize warning signs and connect people to help before a crisis.',false,false),
(2,5,53,'Eating disorder','A serious mental illness involving extreme disturbances in eating behavior and body image.',false,false),
(2,5,54,'Anorexia nervosa','An eating disorder involving severe restriction of food intake driven by fear of weight gain.',false,false),
(2,5,55,'Bulimia nervosa','An eating disorder involving cycles of binge eating followed by purging behaviors.',false,false),
(2,5,56,'PTSD','Post-Traumatic Stress Disorder — a mental health condition triggered by experiencing or witnessing trauma.',false,false),
(2,5,57,'Therapy','Treatment by a trained mental health professional using evidence-based psychological methods.',false,true),
(2,5,58,'Psychiatry','A branch of medicine focused on diagnosing, treating, and preventing mental disorders.',false,true),
(2,5,59,'Stigma','Negative attitudes or discrimination against people with mental health conditions — a major barrier to seeking help.',false,true),
(2,5,60,'Phobia','An intense, irrational fear of a specific object or situation.',false,true),
(2,5,61,'ADHD','Attention-deficit/hyperactivity disorder; difficulty sustaining attention and controlling impulses.',false,true),
(2,5,62,'Obsessive-compulsive disorder (OCD)','A disorder involving recurring, unwanted thoughts and repetitive behaviors.',false,true),
(2,5,63,'Panic disorder','An anxiety disorder with repeated, sudden attacks of intense fear and physical symptoms like a racing heart.',false,true),
(2,5,64,'Social anxiety','Intense fear of being judged or embarrassed in social situations.',false,true),
(2,5,65,'Psychiatrist','A medical doctor who can diagnose mental disorders and prescribe medication.',false,true),
(2,5,66,'Therapist','A professional who provides talk therapy to help people understand and change thought and behavior patterns.',false,true),
(2,5,67,'Crisis line','A free, confidential phone or text service for people in crisis, such as 988, open 24/7.',false,false),
(2,5,68,'Apathy','A lack of strong feeling, interest or concern about things.',true,true),
(2,5,69,'Alienation','Feeling isolated and separated from everyone else.',true,true),
(2,5,70,'Cognitive Therapy','Therapy that helps a person notice and change negative or unhelpful ways of thinking.',true,true),
(3,6,1,'Relationship','A bond or connection between people based on shared experiences, trust, and mutual care.',false,true),
(3,6,2,'Communication','The process of sharing information, thoughts, and feelings using verbal and nonverbal methods.',false,true),
(3,6,3,'Active listening','Fully concentrating on what someone is saying, showing you understand, and responding thoughtfully.',false,true),
(3,6,4,'Assertiveness','The ability to express your thoughts and feelings confidently and respectfully, without aggression.',false,true),
(3,6,5,'Boundary','A limit you set to protect your physical, emotional, and mental well-being in relationships.',false,true),
(3,6,6,'Trust','The firm belief in the reliability, truth, or ability of another person — the foundation of healthy relationships.',false,true),
(3,6,7,'Respect','Treating others with consideration for their feelings, rights, and boundaries.',false,true),
(3,6,8,'Reciprocity','The mutual exchange of benefits, care, or support between people in a healthy relationship.',false,true),
(3,6,9,'Jealousy','A feeling of insecurity or fear of losing something or someone to another — can damage relationships.',false,true),
(3,6,10,'Healthy relationship','A relationship built on trust, respect, communication, equality, and support for each other''s goals.',false,true),
(3,6,11,'I statements','Phrases that express personal feelings without blaming others, beginning with "I feel...".',false,true),
(3,6,12,'Peer pressure','Influence from people your own age to act or think in a certain way.',false,true),
(3,6,13,'Refusal skills','Strategies used to say no to unwanted or risky behaviors.',false,true),
(3,6,14,'Boundaries','Limits a person sets on what they consider acceptable behavior from others.',false,true),
(3,6,15,'Manipulation','Using unfair or dishonest methods to control or influence another person.',false,true),
(3,6,16,'Passive communication','Avoiding conflict by not expressing your needs, which builds resentment.',false,true),
(3,6,17,'Aggressive communication','Expressing needs in a hostile or blaming way that can win arguments but damages trust.',false,true),
(3,6,18,'Nonverbal communication','Messages sent without words, such as eye contact, posture and tone of voice.',false,true),
(3,6,19,'Broken record technique','A refusal strategy of calmly repeating no.',false,true),
(3,6,20,'Delay tactic','A refusal strategy that buys time, such as saying "I need to think about it.".',false,true),
(3,6,21,'Compromise','A solution where each person gives up something to reach an agreement that works for everyone.',true,true),
(3,6,22,'Stereotype','An exaggerated or oversimplified belief about people who belong to a certain group.',true,true),
(3,6,23,'Body Language','Messages you send with your posture, gestures, facial expressions and eye contact.',true,true),
(3,7,24,'Siblings','Brothers and sisters.',false,true),
(3,7,25,'Nuclear family','Two parents and one or more children living in the same home.',false,true),
(3,7,26,'Blended family','A family formed when a single parent remarries, bringing together children from previous relationships.',false,true),
(3,7,27,'Extended family','A family that includes relatives beyond parents and children, such as grandparents, aunts, uncles and cousins.',false,true),
(3,7,28,'Foster care','The temporary placement of children in the homes of adults who are not related to them.',false,true),
(3,7,29,'Affirmation','Positive feedback that helps others feel appreciated and supported.',false,true),
(3,7,30,'Separation','A decision by two married people to live apart from each other.',false,true),
(3,7,31,'Divorce','A legal end to a marriage contract.',false,true),
(3,7,32,'Custody','The legal right to make decisions affecting children and the responsibility for their care.',false,true),
(3,7,33,'Abuse','The physical, mental, emotional, or sexual mistreatment of one person by another.',false,false),
(3,7,34,'Domestic violence','Acts of violence or abuse involving family members.',false,false),
(3,7,35,'Spousal abuse','Domestic violence or abuse directed at a spouse or partner.',false,false),
(3,7,36,'Child abuse','Domestic abuse directed at a child, including physical, emotional, or sexual harm.',false,false),
(3,7,37,'Neglect','The failure to provide for a child''s basic needs.',false,false),
(3,7,38,'Elder abuse','The abuse or neglect of older family members.',false,false),
(3,7,39,'Cycle of violence','The pattern of repeating violent or abusive behaviors from one generation to the next.',false,false),
(3,7,40,'Crisis center','A facility that offers advice and support to people dealing with personal emergencies.',false,false),
(3,7,41,'Adoption','Becoming a permanent legal family for a child.',false,true),
(3,7,42,'Single-parent family','One parent raising one or more children, often after divorce, separation or death.',false,true),
(3,7,43,'Commitment','Making time for family members and working on problems together.',false,true),
(3,8,44,'Peers','People your age who share similar interests.',false,true),
(3,8,45,'Platonic friendship','A friendship with someone of a different gender involving genuine affection, but without romantic involvement.',false,true),
(3,8,46,'Clique','A small circle of friends who exclude people viewed as outsiders.',false,true),
(3,8,47,'Harassment','Persistently annoying or targeting others through hurtful behaviors like name-calling, teasing, or bullying.',false,true),
(3,8,48,'Priorities','The goals, tasks, values, and activities you judge to be most important.',false,true),
(3,8,49,'Intimacy','A closeness between two people that develops over time through genuine connection and trust.',false,false),
(3,8,50,'Infatuation','Exaggerated feelings of intense passion that can feel overwhelming but are often short-lived.',false,true),
(3,8,51,'Abstinence','A deliberate decision to avoid high-risk behaviors, including sexual activity and the use of alcohol, tobacco, and other drugs.',false,true),
(3,8,52,'Self-control','The ability to use responsibility and values to override emotions in the moment.',false,true),
(3,8,53,'Sexually transmitted infections (STIs)','Infectious diseases spread from person to person through sexual contact.',false,false),
(3,8,54,'Casual friendship','A friendship built on shared interests without deep emotional bonds.',false,true),
(3,8,55,'Close friendship','A friendship with deep emotional ties, where you can share thoughts and struggles without judgment.',false,true),
(3,8,56,'Positive peer pressure','Influence from peers that pushes you to try new activities, work harder or avoid risky behavior.',false,true),
