(3,9,61,'Conflict','Any disagreement, struggle, or fight.',false,true),
(3,9,62,'Interpersonal conflicts','Conflicts between two or more people or groups.',false,true),
(3,9,63,'Escalate','To become more serious or intense.',false,true),
(3,9,64,'Negotiation','The use of communication and compromise to settle a disagreement.',false,true),
(3,9,65,'Mediation','Bringing in a neutral third party to help others resolve their conflicts peacefully.',false,true),
(3,9,66,'Confidentiality','Respecting the privacy of both parties and keeping details of a discussion secret.',false,true),
(3,9,67,'Peer mediation','A process in which specially trained students help other students resolve conflicts peacefully.',false,true),
(3,9,68,'Violence','The threatened or actual use of physical force or power to harm another person or damage property.',false,true),
(3,9,69,'Assault','An unlawful physical attack or threat of attack.',false,false),
(3,9,70,'Random violence','Violence committed for no particular reason against an unrelated victim.',false,true),
(3,9,71,'Homicide','The willful killing of one human being by another.',false,false),
(3,9,72,'Sexual violence','Any form of unwelcome sexual contact directed at an individual.',false,false),
(3,9,73,'Bullying','Repeated, deliberate hurtful behavior by someone who has more power than the target.',false,true),
(3,9,74,'Cyberbullying','Bullying that happens through phones, social media, games, or other technology.',false,true),
(3,9,75,'Physical abuse','A pattern of intentionally causing bodily harm or injury to another person.',false,false),
(3,9,76,'Emotional abuse','A pattern of attacking another person''s emotional development and sense of worth.',false,false),
(3,9,77,'Verbal abuse','The use of words to mistreat or injure another person; a form of emotional abuse.',false,false),
(3,9,78,'Stalking','Repeatedly following, harassing, or threatening an individual in person or online.',false,false),
(3,9,79,'Upstander','Someone who speaks up, supports the target or gets help when they see bullying.',false,true),
(3,9,80,'Hate crime','A crime motivated by hatred of a group because of race, religion, disability, sexual orientation or other traits.',false,false),
(4,10,1,'Nutrients','Substances in food that provide energy and materials the body needs to grow, repair, and function.',false,true),
(4,10,2,'Carbohydrates','The body''s primary energy source; should make up 45–65% of daily calories.',false,true),
(4,10,3,'Proteins','Nutrients that build and repair cells, muscles, and tissues; made of amino acids.',false,true),
(4,10,4,'Fats','Nutrients that store energy, protect organs, and support vitamin absorption; essential in moderation.',false,true),
(4,10,5,'Vitamins','Organic compounds needed in small amounts to regulate body functions and prevent disease.',false,true),
(4,10,6,'Minerals','Inorganic substances (calcium, iron, zinc) essential for bone health, blood, and body functions.',false,true),
(4,10,7,'MyPlate','The USDA visual guide showing the five food groups and recommended proportions for healthy eating.',false,true),
(4,10,8,'Calorie','A unit of energy; the amount of energy in food that the body uses to perform functions.',false,true),
(4,10,9,'Dietary fiber','Indigestible plant material that supports digestive health, lowers cholesterol, and controls blood sugar.',false,true),
(4,10,10,'Saturated fat','A type of fat found in animal products that raises LDL (bad) cholesterol when consumed in excess.',false,true),
(4,10,11,'Trans fat','An artificially created fat that raises bad cholesterol and lowers good cholesterol — largely banned.',false,true),
(4,10,12,'Nutrition label','The panel on food packaging showing calorie count, nutrients, and percent daily values.',false,true),
(4,10,13,'Dietary guidelines','Science-based advice from the USDA and HHS on what to eat and drink to promote health.',false,true),
(4,10,14,'Fiber','A type of carbohydrate the body cannot digest; promotes digestive health and reduces disease risk.',false,true),
(4,10,15,'Unsaturated fat','A healthier type of fat, found in foods like nuts, fish and olive oil, that should replace saturated and trans fats.',false,true),
(4,10,16,'Added sugars','Sugars put into foods during processing; the Dietary Guidelines say to keep them under 10% of daily calories.',false,true),
(4,10,17,'Sodium','A mineral found in salt; the Dietary Guidelines say to keep it under 2,300 mg per day.',false,true),
(4,10,18,'Serving size','The amount of food that all the numbers on a Nutrition Facts label are based on.',false,true),
(4,10,19,'Percent Daily Value','How much a serving adds to a day''s needs; 5% or less is low and 20% or more is high.',false,true),
(4,10,20,'Ultra-processed foods','Packaged foods like chips and fast food that are engineered to override your hunger signals.',false,true),
(4,10,21,'Appetite','A desire to eat that comes from emotions or the look and smell of food, not physical need.',true,true),
(4,10,22,'Nutrient-Dense','Foods with a lot of nutrients compared with the number of calories they have.',true,true),
(4,10,23,'Cross-Contamination','The spread of bacteria or other germs from one food or surface to another.',true,true),
(4,11,24,'Body Mass Index (BMI)','A ratio of weight to height used as a screening tool for healthy weight — not a diagnosis.',false,true),
(4,11,25,'Metabolism','The rate at which your body converts food into energy — affects weight management.',false,true),
(4,11,26,'Basal metabolic rate','The number of calories your body needs to maintain basic functions at rest.',false,true),
(4,11,27,'Caloric balance','The relationship between calories consumed and calories burned through activity.',false,true),
(4,11,28,'Body image','The way you see and feel about your physical appearance.',false,true),
(4,11,29,'Eating disorder','A serious mental illness with extreme disturbances in eating behavior, body image, and weight.',false,false),
(4,11,30,'Anorexia nervosa','An eating disorder involving extreme restriction of food intake driven by fear of weight gain.',false,false),
(4,11,31,'Bulimia nervosa','An eating disorder with cycles of binge eating followed by purging.',false,false),
(4,11,32,'Binge eating disorder','Recurrent episodes of eating large amounts of food rapidly without purging — most common ED.',false,false),
(4,11,33,'Fad diet','A popular diet promising quick weight loss that typically lacks scientific support and is unsustainable.',false,true),
(4,11,34,'Weight management','A long-term approach to maintaining a healthy weight through balanced nutrition and physical activity.',false,true),
(4,11,35,'Obesity','A condition of excess body fat that increases risk of diabetes, heart disease, and other conditions.',false,true),
(4,11,36,'Body composition','The ratio of fat mass to lean (muscle, bone, water) mass in the body.',false,true),
(4,11,37,'Intuitive eating','An approach to food that honors internal hunger and fullness cues rather than external diet rules.',false,true),
(4,11,38,'Mindful eating','Paying attention to hunger and fullness cues and avoiding emotional eating.',false,true),
(4,11,39,'Emotional eating','Eating in response to feelings rather than hunger.',false,true),
(4,11,40,'Orthorexia','An obsessive focus on "clean" or "pure" eating to the point of harm.',false,false),
(4,11,41,'All Foods Fit','The idea that balance, variety and moderation matter more than labeling foods good or bad.',false,true),
(4,11,42,'Underweight','A BMI below 18.5, which may signal a nutritional deficiency or eating disorder.',false,true),
(4,11,43,'Overweight','A BMI of 25–29.9, linked to increased risk for chronic conditions.',false,true),
(4,11,44,'Weight Cycling','Repeatedly losing and then regaining weight.',true,true),
(4,11,45,'Dietary Supplements','Pills, powders or liquids taken to add nutrients to your diet.',true,true),
(4,11,46,'Performance Enhancers','Substances taken to try to improve athletic performance, many of them unsafe.',true,true),
(4,12,47,'Physical activity','Any movement that uses energy — from walking to organized sports.',false,true),
(4,12,48,'Exercise','Planned, structured, repetitive physical activity done to improve or maintain fitness.',false,true),
